(function(root,data){if(typeof module==="object"&&module.exports)module.exports=data;else root.GrowingMathStudyFocus=data;})(typeof window!=="undefined"?window:globalThis,{"tri-lines":{"exam":[1,3,8,10],"mistake":[9],"segments":["易考点：由中点求边长，由角平分线求角度；中线把三角形分成面积相等的两部分。","易错点：中线只保证对边被平分，不保证垂直；高的垂足也不一定是中点。"],"required":["tri-lines-application-1","tri-lines-application-9"]},"tri-angles":{"exam":[4,6,9,10],"mistake":[5,6,9],"segments":["外角：三角形一边与另一边的延长线所组成的角，叫三角形的外角。","易考点：用内角和180°与外角定理列式，结合角平分线求角。","易错点：外角等于两个不相邻内角之和；与相邻内角的关系是互补，不能把两种关系混用。"],"required":["tri-angles-application-4","tri-angles-application-5"]},"tri-inequality":{"exam":[2,6,9],"mistake":[4,8,10],"segments":["易考点：已知两边a、b，第三边x满足|a−b|<x<a+b；整数边长要在开区间内枚举。","易错点：两边之和等于第三边时不能围成三角形；等腰三角形的腰、底不明时要分类并排除不成立的情况。"],"required":["tri-inequality-application-2","tri-inequality-application-4"]},"congruence":{"exam":[4,6,9],"mistake":[3,10],"segments":["易考点：按全等符号中的顶点顺序找对应边、对应角，再求长度、角度或周长。","易错点：旋转或翻转不改变对应关系；不能按图上位置、线段长相猜对应顶点。"],"required":["congruence-application-4","congruence-application-3"]},"cong-sss":{"exam":[5,7,9],"mistake":[6],"segments":["SSS：“边边边”的简写，要求三组对应边分别相等。","易考点：逐条写出三组对应边相等；公共边也要作为一组条件列出。","易错点：只有两组边相等不够；第三组对应边长度不同，不能用SSS。"],"required":["cong-sss-application-5","cong-sss-application-6"]},"cong-sas":{"exam":[1,4,10],"mistake":[2,3],"segments":["夹角：两条边在共同顶点处所夹的角。SAS中的角必须处在所给两边之间。","易考点：先定位两条已知边，再核对它们之间的夹角；公共边、对顶角可补条件。","易错点：已知角必须是两边的夹角；两边及一边的对角相等（SSA）一般不能判全等。"],"required":["cong-sas-application-1","cong-sas-application-2"]},"cong-asa":{"exam":[4,5,9,10],"mistake":[2,6],"segments":["易考点：两角及夹边用ASA，两角及对应非夹边用AAS；可借平行线找相等角。","易错点：三个角分别相等没有固定边长，大小可以不同，不能用AAA判全等。"],"required":["cong-asa-application-4","cong-asa-application-2"]},"cong-hl":{"exam":[4,5,10],"mistake":[1,6,8],"segments":["斜边与直角边：直角所对的边是斜边；夹着直角的两条边是直角边。","易考点：先确认两个直角三角形，再找斜边与一条对应直角边相等。","易错点：HL不能用于一般三角形；即使都是直角三角形，只有斜边相等仍缺条件。"],"required":["cong-hl-application-4","cong-hl-application-1"]},"perp-bisector":{"exam":[4,7,10],"mistake":[2,6],"segments":["垂直平分线：经过一条线段的中点，并且垂直于这条线段的直线。","易考点：垂直平分线上的点到两端等距，可用于列方程、转化线段和求周长。","易错点：“垂直”与“平分”缺一不可；它比较到线段两个端点的距离，不是到任意点的距离。"],"required":["perp-bisector-application-4","perp-bisector-application-2"]},"angle-bisector":{"exam":[4,5,9],"mistake":[2,7,8],"segments":["易考点：由角平分线得到两条垂距相等；反过来须是角内部的等距点。","易错点：点到角两边的距离是垂线段长，不能把到顶点的距离或斜着连接的线段当作垂距。"],"required":["angle-bisector-application-4","angle-bisector-application-2"]},"isosceles":{"exam":[4,8,10],"mistake":[7],"segments":["等腰三角形：有两条边相等的三角形。相等的两边叫腰，另一边叫底边；两腰的夹角叫顶角。","易考点：等边对等角、等角对等边；顶角到底边的三线合一可配合勾股定理求高。","易错点：只说“一个角”时，要区分它是顶角还是底角，不能漏解。"],"required":["isosceles-application-4","isosceles-application-7"]},"equilateral":{"exam":[4,7,8,9],"mistake":[3,6,10],"segments":["易考点：三边相等、三角均为60°；作高后底边被平分，可求高与面积。","易错点：由一个60°角推出等边，必须同时有等腰等条件，不能只凭一个角下结论。"],"required":["equilateral-application-4","equilateral-application-3"]},"square-root":{"exam":[1,2,4,5],"mistake":[6,7,9],"segments":["易考点：区分“a的平方根”和“√a”：正数有正负两个平方根，算术平方根只取非负值。","易错点：解x²=a可能有两个根，但求实际边长只取正值；√(a²)=|a|，不能漏绝对值。"],"required":["square-root-application-1","square-root-application-6"]},"root-estimate":{"exam":[4,5,9,10],"mistake":[7,9],"segments":["易考点：用相邻完全平方数夹住被开方数，再确定根的整数部分或小数范围。","易错点：估计不等于四舍五入；求一位小数时要比较舍入分界，不能只取整数部分。"],"required":["root-estimate-application-4","root-estimate-application-7"]},"cube-root":{"exam":[4,5,7,9],"mistake":[1,8,10],"segments":["易考点：若x³=a，则x是a的立方根；正数、负数、0各有唯一实数立方根。","易错点：负数的立方根是负数，不写±；减去负的立方根时还要处理外面的减号。"],"required":["cube-root-application-4","cube-root-application-1"]},"real-types":{"exam":[4,5,9],"mistake":[3,7,9,10],"segments":["有理数：能写成p/q（p、q为整数且q≠0）的数；包括整数、有限小数和无限循环小数。","易考点：先化简表达式，再按有理数或无限不循环小数分类。","易错点：含根号或π不保证无理；无限循环小数有理，两个无理数的和也可能有理。"],"required":["real-types-application-4","real-types-application-3"]},"real-line":{"exam":[5,7,9],"mistake":[3,6,8],"segments":["数轴：规定了原点、正方向和单位长度的直线。","易考点：数轴右大左小，绝对值表示到原点的距离；两点距离是坐标差的绝对值。","易错点：负数比较时绝对值越大反而越小；到某点等距离的位置可能在它左右两侧。"],"required":["real-line-application-5","real-line-application-3"]},"approximate":{"exam":[1,4,5,6],"mistake":[9,10],"segments":["易考点：看保留位的后一位四舍五入；末尾0须保留，以表示指定精确度。","易错点：不能把3.00简写成3来表达百分位精度；中间过早舍入可能改变最终结果。"],"required":["approximate-application-1","approximate-application-9"]},"pythagoras":{"exam":[1,3,4,5,10],"mistake":[6,9,10],"segments":["易考点：确认直角后，求斜边用平方和，求直角边用斜边平方减去另一直角边平方。","易错点：边长不能直接相加；从平方求长度只取正值，且不要把半条线段当作完整边长。"],"required":["pythagoras-application-1","pythagoras-application-6"]},"pyth-converse":{"exam":[2,4,7,10],"mistake":[3,5,6],"segments":["易考点：先找最长边c，再计算另两边平方和，检验是否等于c²以判断直角。","易错点：能构成三角形不等于直角三角形；直角所对的一定是最长边，不能随意换边。"],"required":["pyth-converse-application-2","pyth-converse-application-3"]},"pyth-apply":{"exam":[4,5,7,8],"mistake":[9,10],"segments":["易考点：把梯子、矩形对角线或垂直路线转化为直角三角形，明确单位和所求边。","易错点：梯长是斜边，梯脚移动量不直接等于梯顶下降量；折线路程也不等于起终点距离。"],"required":["pyth-apply-application-4","pyth-apply-application-9"]},"coordinates":{"exam":[1,4,5,9],"mistake":[4,6,7,10],"segments":["有序数对：用有先后顺序的两个数表示位置，交换顺序通常会改变所表示的点。","易考点：坐标先横后纵；到x轴的距离是|y|，到y轴的距离是|x|。","易错点：负坐标不表示负距离；同一竖直或水平线段的长度要计算坐标差。"],"required":["coordinates-application-1","coordinates-application-4"]},"quadrants":{"exam":[4,5,7,9],"mistake":[2,6,10],"segments":["易考点：依次记住四象限符号(+,+)、(−,+)、(−,−)、(+,−)，转化为坐标的不等式条件。","易错点：坐标轴上的点不在任何象限；“在坐标轴上”要考虑横坐标为0或纵坐标为0两种情况。"],"required":["quadrants-application-4","quadrants-application-2"]},"translation":{"exam":[4,5,7,9],"mistake":[8,9,10],"segments":["易考点：向右横坐标加、向上纵坐标加；先求平移量，再对所有顶点使用相同规则。","易错点：平移保持图形长度和面积，不能只移动一个顶点或交换横纵坐标。"],"required":["translation-application-4","translation-application-8"]},"reflection":{"exam":[4,5,6,9],"mistake":[2,4,8],"segments":["轴对称：沿一条直线折叠后能重合的两图形互为轴对称；对应点连线被对称轴垂直平分。","易考点：关于x轴对称变y的符号，关于y轴对称变x的符号，关于原点对称两者都变号。","易错点：不要把对称轴名称与要变号的坐标混淆；关于x=5对称也不是简单把横坐标取相反数。"],"required":["reflection-application-4","reflection-application-2"]},"function-variable":{"exam":[1,3,7,9],"mistake":[10],"segments":["变量与常量：在某个变化过程中，数值改变的量是变量，数值保持不变的量是常量。","易考点：给定每一个允许的自变量值，函数值必须唯一；实际范围由数量、时间等条件决定。","易错点：不同x可以对应同一个y；只要每个x对应唯一的y，仍然可以构成函数。"],"required":["function-variable-application-1","function-variable-application-10"]},"linear-function":{"exam":[3,4,6,9],"mistake":[1,2,6,9],"segments":["易考点：认准y=kx+b且k≠0；正比例还须b=0，参数题需同时核对两条件。","易错点：不能只检查常数项为0而忘记一次项系数非零；常值函数不属于本节的一次函数。"],"required":["linear-function-application-3","linear-function-application-1"]},"line-graph":{"exam":[4,5,7,9],"mistake":[3,6,10],"segments":["易考点：取两个不同点描直线；求y轴交点令x=0，求x轴交点令y=0。","易错点：点在图象上须同时满足横纵坐标关系，不能只看横坐标或凭图形猜测。"],"required":["line-graph-application-4","line-graph-application-3"]},"line-monotone":{"exam":[4,6,7,9],"mistake":[1,3,8],"segments":["易考点：增减看k的正负；限定区间内的最值结合增减性在对应端点求。","易错点：看k而不是b；递减函数中，函数值较大对应的自变量反而较小。"],"required":["line-monotone-application-4","line-monotone-application-1"]},"line-coefficients":{"exam":[6,7,9,10],"mistake":[5,8,9],"segments":["待定系数法：先把未知系数写入已知形式，再利用给定条件列方程确定系数的方法。","易考点：设y=kx+b，把两个不同点分别代入求k、b，再回代检验。","易错点：代入负坐标要保留符号；已知与某直线平行时，继承的是k，不能照抄b。"],"required":["line-coefficients-application-6","line-coefficients-application-5"]},"line-model":{"exam":[1,6,7,9],"mistake":[9,10],"segments":["易考点：固定量写成b，单位变化量写成k；比较两方案先求相等点，再按范围比较。","易错点：实际数量和容量限制不能忽略；按实际时长计费与不足一小时按一小时计费不能混用。"],"required":["line-model-application-1","line-model-application-9"]},"line-system":{"exam":[1,5,9,10],"mistake":[3,6,10],"segments":["易考点：交点坐标同时满足两个方程，联立求x后还须求y，并写成有序数对。","易错点：两直线平行且不重合没有公共解；“不比另一方案贵”应包含费用相等的边界。"],"required":["line-system-application-1","line-system-application-3"]},"survey":{"exam":[3,4,7,9],"mistake":[8,9,10],"segments":["总体、样本与样本容量：总体是全部考察对象的全体，样本是从中抽取的一部分对象；样本容量是样本中的个体数。","易考点：区分总体、样本和样本容量；按总体结构随机抽样，按比例分配抽取人数。","易错点：样本人数多不代表无偏差；只调查特定社团或特定场所的人，可能不能代表总体。"],"required":["survey-application-3","survey-application-8"]},"charts":{"exam":[4,5,6,9],"mistake":[8],"segments":["扇形统计图：用整个圆表示总体，各扇形圆心角占360°的比例表示各部分所占比例。","易考点：数量比较用条形图，趋势用折线图，构成用扇形图；圆心角=比例×360°。","易错点：先读坐标轴起点、刻度和单位；截断纵轴后的柱高比不等于真实数量比。"],"required":["charts-application-4","charts-application-8"]},"price-study":{"exam":[4,5,7,9],"mistake":[1,8,10],"segments":["易考点：统一商品质量、规格、数量和单位，再把优惠、运费计入总支出。","易错点：单包价格低不等于单位价格低；有赠品、整包购买时要比较满足同一需求的实际支出。"],"required":["price-study-application-4","price-study-application-1"]},"frequency":{"exam":[4,5,7,9],"mistake":[8,10],"segments":["易考点：频率=频数÷总数；类别不重不漏时，频数和等于总数，频率和等于1。","易错点：不同样本量合并时，先合并频数和总数再相除，不能简单平均两个频率。"],"required":["frequency-application-4","frequency-application-8"]},"histogram":{"exam":[1,4,6,9],"mistake":[4,9,10],"segments":["组距：一组的上、下边界之差；等组距直方图的柱高可表示频数。","易考点：按组界逐个统计数据，频数和必须等于总数；区间[a,b)包含a但不包含b。","易错点：组界不能重复计数；只有分组频数时，不能任意拆分组内人数来求更细范围。"],"required":["histogram-application-1","histogram-application-4"]},"vision-study":{"exam":[5,6,7,9],"mistake":[8,10],"segments":["易考点：说明目标总体、抽样方式、样本量和指标标准；用样本比例估计相应总体人数。","易错点：相关不能直接证明因果；抽样比例与总体结构不一致时，不能把样本简单合并当总体比例。"],"required":["vision-study-application-5","vision-study-application-8"]},"random-event":{"exam":[4,5,6,9],"mistake":[1,6,10],"segments":["易考点：在给定条件下，区分必然、不可能与随机事件；保证发生要考虑最坏情况。","易错点：“可能发生”不是“必定发生”；判随机事件可分别举一个发生和一个不发生的结果。"],"required":["random-event-application-4","random-event-application-1"]},"probability":{"exam":[4,5,7,8],"mistake":[6,9],"segments":["易考点：在基本结果等可能时，概率=有利结果数÷全部结果数；多次抽取可按编号列举。","易错点：不能把颜色或点数和等类别直接当等可能结果；不放回抽取要区分顺序和剩余个数。"],"required":["probability-application-4","probability-application-6"]},"frequency-prob":{"exam":[3,6,7,9],"mistake":[1,5,8,10],"segments":["易考点：保持条件不变，大量重复试验，用频率估计概率；合并频率先合并次数。","易错点：理论概率不是有限次数必达的比例；独立试验不会因前几次结果而“补偿”下一次。"],"required":["frequency-prob-application-3","frequency-prob-application-1"]},"parallelogram":{"exam":[4,5,6,9],"mistake":[2,8],"segments":["易考点：用对边相等、邻角互补和对角线互相平分列式求边、角及周长。","易错点：一般平行四边形的两条对角线不一定相等，不能把一条的一半当作另一条的一半。"],"required":["parallelogram-application-4","parallelogram-application-2"]},"parallel-judge":{"exam":[4,5,6,9],"mistake":[1,3],"segments":["易考点：判定可用两组对边相等、对角线互相平分，或同一组对边既平行又相等。","易错点：平行和相等必须落在同一组对边上；一组平行、另一组相等可能是等腰梯形。"],"required":["parallel-judge-application-4","parallel-judge-application-1"]},"rectangle":{"exam":[4,5,8,9],"mistake":[10],"segments":["易考点：矩形有四个直角；对角线相等且互相平分，结合勾股定理求边长。","易错点：矩形中的辅助四边形不自动是矩形；判定还须证明直角等充分条件。"],"required":["rectangle-application-4","rectangle-application-10"]},"rhombus":{"exam":[5,7,9],"mistake":[1,3,7,9],"segments":["易考点：四边相等，对角线垂直且互相平分；面积为两对角线乘积的一半。","易错点：求边长时用半条对角线构成直角三角形；求面积不能漏除以2。"],"required":["rhombus-application-5","rhombus-application-1"]},"square":{"exam":[3,7,9,10],"mistake":[1,6,8],"segments":["易考点：正方形兼有矩形与菱形的性质；对角线长是边长的√2倍。","易错点：矩形或菱形都不一定是正方形，需补上邻边相等或直角等对应条件。"],"required":["square-application-3","square-application-1"]},"midline":{"exam":[3,4,5,8],"mistake":[2,9],"segments":["易考点：连接两边中点得到中位线，它平行于第三边且长为第三边的一半。","易错点：中位线连接两个中点，中线连接顶点与对边中点；小三角形边长减半时，面积是原来的四分之一。"],"required":["midline-application-3","midline-application-2"]},"trapezoid":{"exam":[3,4,7,8],"mistake":[2,5,6],"segments":["易考点：本课程采用只有一组对边平行的定义；面积=(上底+下底)×高÷2。","易错点：高是两底间的垂直距离，不是斜腰；本定义下平行四边形不是梯形。"],"required":["trapezoid-application-3","trapezoid-application-2"]},"iso-trapezoid":{"exam":[4,6,9,10],"mistake":[7,8,9],"segments":["易考点：两腰相等，同底角相等，对角线相等；作高把问题转为矩形与直角三角形。","易错点：同底角相等不表示四个角都相等；求腰时水平差取两底差的一半。"],"required":["iso-trapezoid-application-4","iso-trapezoid-application-7"]},"factor":{"exam":[4,7,9],"mistake":[3,6,8],"segments":["易考点：公因式系数取最大公因数，共有字母取最低次幂；可把整式整体作为公因式。","易错点：每一项都要除以公因式；某项恰等于公因式时剩下1，不能漏写。"],"required":["factor-application-4","factor-application-3"]},"factor-concept":{"exam":[1,4,5,9],"mistake":[6,8,10],"segments":["易考点：目标是把多项式写成整式的积；用展开检验是否还原原多项式。","易错点：从乘积展开成和不是因式分解；代入一个数碰巧相等不能证明恒等。"],"required":["factor-concept-application-1","factor-concept-application-6"]},"factor-difference":{"exam":[1,5,7,10],"mistake":[3,7,8],"segments":["易考点：认出两个平方项之差，写成和乘差；先提公因式，再检查能否继续分解。","易错点：平方和不能套用平方差公式；“差的平方”与“平方差”不能混淆，分解也不能停在仍可继续分解的中间形式。"],"required":["factor-difference-application-1","factor-difference-application-3"]},"factor-perfect":{"exam":[4,5,6,9],"mistake":[2,10],"segments":["易考点：首尾是平方项，中间项恰为两数乘积的±2倍，才能写成(a±b)²。","易错点：减法型完全平方的末项仍为正；两个非负平方之和为0时，每个平方都必须为0。"],"required":["factor-perfect-application-4","factor-perfect-application-2"]},"definition":{"exam":[1,4,8,10],"mistake":[3,4,5,10],"segments":["易考点：先看原形式：分子分母是整式，且分母含字母，才叫分式。","易错点：有分数线不一定是分式，π是常数；不能先约分再判断原式是否为分式。"],"required":["definition-application-1","definition-application-3"]},"meaning":{"exam":[1,5,6,9],"mistake":[8,10],"segments":["易考点：令原分母不等于0；分母是因式乘积时，逐个排除使因式为0的值。","易错点：约分不会消除原分母的限制；化简后看不到的零点也必须排除。"],"required":["meaning-application-1","meaning-application-8"]},"zero":{"exam":[2,4,5,9],"mistake":[1,3,8,10],"segments":["易考点：先令分子为0求候选值，再剔除使原分母为0的值。","易错点：0/0无意义，不是0；即使分子能等于0，分式也可能永远不取0。"],"required":["zero-application-2","zero-application-1"]},"property":{"exam":[3,6,9],"mistake":[1,8,10],"segments":["易考点：分子分母同时乘或除以同一个非零整式，值不变；每一项都要变换。","易错点：不能改成同时加减；同乘含字母的式子时，要补充它不等于0的条件。"],"required":["property-application-3","property-application-1"]},"sign":{"exam":[1,5,9,10],"mistake":[7,8,10],"segments":["易考点：分式、分子、分母三处中同时改两处符号，值不变；b−a=−(a−b)。","易错点：相反式平方后相等，不要再多加负号；外面的减号也要与分母变号一起处理。"],"required":["sign-application-1","sign-application-7"]},"reduce":{"exam":[4,5,9,10],"mistake":[1,6],"segments":["易考点：分子分母先分解因式，只约去共同的非零因式，并保留原分母限制。","易错点：加减式中的一项不是因式，不能直接消掉；约分后仍要保留被约去因式的取值限制。"],"required":["reduce-application-4","reduce-application-1"]},"common":{"exam":[1,4,7,10],"mistake":[2,5,6,9],"segments":["易考点：最简公分母取系数最小公倍数、各因式的最高次幂；先分解分母更容易看清。","易错点：分母乘了什么，分子也须同乘；不要把已有的共同因式重复乘入公分母。"],"required":["common-application-1","common-application-2"]},"add":{"exam":[2,4,6,9],"mistake":[7,8],"segments":["易考点：同分母只加减分子，异分母先通分，结果还要约分化简。","易错点：减去多项式分子必须加括号，去括号时每项都变号；整式也要一起通分。"],"required":["add-application-2","add-application-7"]},"multiply":{"exam":[4,5,8,10],"mistake":[7,9],"segments":["易考点：分式乘除先分解、约分；除以一个分式转化为乘它的倒数。","易错点：除式不仅要有意义，还不能为0；乘除混合按从左到右计算。"],"required":["multiply-application-4","multiply-application-7"]},"equation":{"exam":[3,4,7,10],"mistake":[6,9],"segments":["易考点：两边同乘最简公分母，解整式方程后检验原分母；应用题按等量关系列方程。","易错点：去分母时每一项都要乘，包括没有分母的常数项，不能漏乘。"],"required":["equation-application-3","equation-application-6"]},"extraneous":{"exam":[5,7,10],"mistake":[1,4,8,9],"segments":["易考点：增根使原分母为0，必须舍去；参数题先找可能的增根，再代入去分母后的方程。","易错点：去分母所得候选根不是直接答案；若候选根全是增根，原方程无解。"],"required":["extraneous-application-5","extraneous-application-1"]},"radical-domain":{"exam":[4,6,7,9],"mistake":[3,5,8,9],"segments":["易考点：根号内须非负；多个条件取交集，根式在分母时还须排除0。","易错点：普通根式允许被开方数为0，分母根式却不允许；端点是否能取要分别检查。"],"required":["radical-domain-application-4","radical-domain-application-3"]},"radical-simplify":{"exam":[1,6,8,9],"mistake":[2,3,5,7],"segments":["易考点：提出完全平方因子；√(a²)=|a|，结合字母范围去绝对值。","易错点：负数平方再开算术平方根得到非负值；字母为负时不能直接写回原字母。"],"required":["radical-simplify-application-1","radical-simplify-application-2"]},"radical-multiply":{"exam":[4,5,7,9],"mistake":[3,6,10],"segments":["易考点：满足非负和除数非零条件后合并根式；系数也要相乘相除，结果化简。","易错点：分母有理化时分子分母须同乘；带加减的分母可用共轭式，不能只把分母平方。"],"required":["radical-multiply-application-4","radical-multiply-application-3"]},"radical-add":{"exam":[1,5,7,9],"mistake":[3,6,8],"segments":["易考点：先化成最简二次根式，再合并同类项，只加减系数。","易错点：不能把和直接放入根号；未化简前看似不同的根式，可能实际同类。"],"required":["radical-add-application-1","radical-add-application-3"]}});
